java.awt.image.BufferedImage exactSizeThumb = net.coobird.thumbnailator.Thumbnails.of(sourceImage)
    .size(120, 50)
    .keepAspectRatio(false)
    .asBufferedImage();

assert exactSizeThumb.getWidth() == 120 : "Width should be exactly 120 when keepAspectRatio is false";
assert exactSizeThumb.getHeight() == 50 : "Height should be exactly 50 when keepAspectRatio is false";

java.awt.image.BufferedImage keptRatioThumb = net.coobird.thumbnailator.Thumbnails.of(sourceImage)
    .size(120, 50)
    .keepAspectRatio(true)
    .asBufferedImage();

assert keptRatioThumb.getWidth() <= 120 : "Width should be bounded by 120 when keepAspectRatio is true";
assert keptRatioThumb.getHeight() <= 50 : "Height should be bounded by 50 when keepAspectRatio is true";

double originalRatio = (double) sourceImage.getWidth() / sourceImage.getHeight();
double keptRatio = (double) keptRatioThumb.getWidth() / keptRatioThumb.getHeight();
assert Math.abs(originalRatio - keptRatio) < 0.15 : "Aspect ratio should be approximately preserved";

System.out.println("__CHECK__ keepAspectRatio " + exactSizeThumb.getWidth() + "x" + exactSizeThumb.getHeight() + " vs " + keptRatioThumb.getWidth() + "x" + keptRatioThumb.getHeight());
